import { MeshStandardNodeMaterial, Group } from 'three/webgpu';
import { texture, uv, uniform, vec3, vec4, float, mix, smoothstep, distance, vec2 } from 'three/tsl';
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'hub-pricing-badge';
  group.position.set(1.25, 0.7000000000000001, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 0.9;
  const height = 0.32;

  const geometry = new THREE.PlaneGeometry(width, height, 32, 8);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const inkColor = new THREE.Color('#16161d');
  const paperColor = new THREE.Color('#e8ecf2');
  const accentColor = new THREE.Color('#ff2a38');

  const uHover = uniform(0.0);
  const uAccent = uniform(1.0);

  const material = new MeshStandardNodeMaterial();
  material.metalness = 0.45;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.transparent = true;

  const vUv = uv();
  // capsule shape via rounded distance field on uv, edge-light near border
  const centered = vUv.sub(vec2(0.5, 0.5));
  const edgeDist = distance(vec2(centered.x.mul(width), centered.y.mul(height)).length(), 0.0);

  const baseTex = texture(map, vUv);
  const baseColor = mix(vec3(inkColor.r, inkColor.g, inkColor.b), vec3(paperColor.r, paperColor.g, paperColor.b), baseTex.r.mul(0.15).add(0.85));

  // edge glow: stronger near border of uv (0 or 1) on x axis (capsule ends)
  const edgeX = smoothstep(0.0, 0.06, vUv.x).oneMinus().add(smoothstep(0.94, 1.0, vUv.x));
  const edgeGlow = vec3(accentColor.r, accentColor.g, accentColor.b).mul(edgeX.mul(uAccent));

  const finalColor = baseColor.add(edgeGlow);

  material.colorNode = vec4(finalColor, 1.0);
  material.emissiveNode = edgeGlow.mul(0.6);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-pricing-badge-mesh';
  group.add(mesh);

  // interactive: hover rise-in, click emit
  let baseY = group.position.y;
  const timelines = [];

  const onHoverIn = () => {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' });
    tl.to(uHover, { value: 1.0, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(uAccent, { value: 1.6, duration: 0.7, ease: 'power3.out' }, 0);
    timelines.push(tl);
  };

  const onHoverOut = () => {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' });
    tl.to(uHover, { value: 0.0, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(uAccent, { value: 1.0, duration: 0.5, ease: 'power2.out' }, 0);
    timelines.push(tl);
  };

  const onClick = () => {
    const tl = gsap.timeline();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'back.out' });
    timelines.push(tl);

    if (group.userData.emit) {
      group.userData.emit('hub-pricing.select', { source: 'hub-pricing-badge' });
    }
  };

  group.userData.handlers = {
    onHoverIn,
    onHoverOut,
    onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return group;
}
